export type EvidenceId =
  | "public-source"
  | "governed-acquisition"
  | "raw-archive"
  | "cleaning-deduplication"
  | "ocr-enrichment"
  | "quarantine"
  | "eligibility"
  | "provenance-lineage"
  | "source-inspector"
  | "investigation-evidence"
  | "evidence-lenses"
  | "verification"
  | "findings-reports"
  | "evidence-export"
  | "evidence-continuity";

export type EvidenceVisualType =
  | "public-source" | "acquisition" | "archive" | "cleaning" | "ocr-enrichment"
  | "quarantine" | "eligibility" | "lineage" | "source-inspector" | "investigation-scope"
  | "lens-evidence" | "verification" | "report-evidence" | "export" | "continuity";

export type EvidenceNodeKind = "source" | "record" | "derived" | "gate" | "scope" | "observation" | "human" | "limitation";

export interface EvidenceNode {
  id: string;
  label: string;
  kind: EvidenceNodeKind;
  state: string;
  meaning: string;
  requires: string[];
  doesNot: string[];
  x: number;
  y: number;
}

export interface EvidenceEdge { from: string; to: string; label: string; style?: "solid" | "derived" | "blocked" | "unavailable"; }

export interface EvidenceDefinition {
  id: EvidenceId;
  name: string;
  shortName: string;
  subtitle: string;
  purpose: string;
  mechanism: string;
  preserves: string[];
  states: string[];
  technicalFlow: string[];
  boundary: string;
  visualType: EvidenceVisualType;
  group: "Collect & Preserve" | "Prepare & Govern" | "Trace & Inspect" | "Analyze & Conclude" | "Export & Continue";
  visualTitle: string;
  visualSummary: string;
  nodes: EvidenceNode[];
  edges: EvidenceEdge[];
}

const node = (id: string, label: string, kind: EvidenceNodeKind, state: string, meaning: string, requires: string[], doesNot: string[], x: number, y: number): EvidenceNode => ({ id, label, kind, state, meaning, requires, doesNot, x, y });

