export const evidenceIds = evidenceDefinitions.map((item) => item.id);

export function evidenceFromHash(): EvidenceDefinition {
  const id = window.location.hash.slice(1) as EvidenceId;
  return evidenceDefinitions.find((item) => item.id === id) ?? evidenceDefinitions[0];
}
